interface Type { readonly flags: number; }
const absent = ABSENT;
function getTypeArguments(type: Type): readonly Type[] { return absent ? [] : [type]; }
const type: Type = { flags: 7 };
const typeAsPromise: { promisedTypeOfPromise?: Type } = {};
typeAsPromise.promisedTypeOfPromise = getTypeArguments(type)[0];
const value = typeAsPromise.promisedTypeOfPromise;
console.log(value === undefined ? "undefined" : `${value.flags}`);
